/*
 * Audio Check
 * Generated by PRG32-Construction-Kit from the saved Blocks JSON.
 * Edit the blocks, then regenerate this file.
 *
 * HOW TO READ THIS FILE
 * A PRG32 cartridge is a small program that the PRG32 firmware loads into memory
 * and calls through three functions (the 'cartridge lifecycle'):
 *   audio_check_init()    once, when the game starts ('when game starts' blocks);
 *   audio_check_update()  once per frame, to move things ('every frame' blocks);
 *   audio_check_draw()    once per frame, after update, to paint the screen ('draw' blocks).
 * The file has five parts: 1 constants, 2 kit helper functions, 3 pictures,
 * 4 game state (the variables), 5 the three lifecycle functions.
 * Above every block's code a comment repeats the block in words; beside many lines
 * a second comment explains that line.
 *
 * RULES THIS C FOLLOWS
 * - Freestanding C99: no standard library (no printf, no malloc), because a
 *   cartridge runs without an operating system. Everything it needs is either in
 *   the firmware (functions named prg32_...) or written below in part 2.
 * - Every number is a 32-bit whole number (int). There is no floating point:
 *   7 / 2 is 3, and fractions are made with scaled numbers (256 means 1.0).
 * - The same blocks always produce exactly the same file.
 */
#include <stdint.h>                                     /* exact-size types: uint8_t, int16_t, uint32_t, ... */
#include "prg32.h"                                      /* the PRG32 firmware functions and constants */

/* ==========================================================================
 * 1. CONSTANTS
 * #define gives a name to a number. #ifndef ... #endif defines the name only when
 * prg32.h has not already done so. Colours are RGB565 numbers: 16 bits holding
 * 5 bits of red, 6 of green and 5 of blue.
 * ========================================================================== */
#ifndef PRG32_COLOR_BLACK
#define PRG32_COLOR_BLACK 0x0000                        /* red 0/31, green 0/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_WHITE
#define PRG32_COLOR_WHITE 0xFFFF                        /* red 31/31, green 63/63, blue 31/31 */
#endif
#ifndef PRG32_COLOR_RED
#define PRG32_COLOR_RED 0xF800                          /* red 31/31, green 0/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_GREEN
#define PRG32_COLOR_GREEN 0x07E0                        /* red 0/31, green 63/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_BLUE
#define PRG32_COLOR_BLUE 0x001F                         /* red 0/31, green 0/63, blue 31/31 */
#endif
#ifndef PRG32_COLOR_YELLOW
#define PRG32_COLOR_YELLOW 0xFFE0                       /* red 31/31, green 63/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_CYAN
#define PRG32_COLOR_CYAN 0x07FF                         /* red 0/31, green 63/63, blue 31/31 */
#endif
#ifndef PRG32_COLOR_MAGENTA
#define PRG32_COLOR_MAGENTA 0xF81F                      /* red 31/31, green 0/63, blue 31/31 */
#endif
#ifndef PRG32_COLOR_ORANGE
#define PRG32_COLOR_ORANGE 0xFD20                       /* red 31/31, green 41/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_PINK
#define PRG32_COLOR_PINK 0xFE19                         /* red 31/31, green 48/63, blue 25/31 */
#endif
#ifndef PRG32_COLOR_GRAY
#define PRG32_COLOR_GRAY 0x8410                         /* red 16/31, green 32/63, blue 16/31 */
#endif
#ifndef PRG32_COLOR_DARK_GRAY
#define PRG32_COLOR_DARK_GRAY 0x4208                    /* red 8/31, green 16/63, blue 8/31 */
#endif
#ifndef PRG32_COLOR_BROWN
#define PRG32_COLOR_BROWN 0xA145                        /* red 20/31, green 10/63, blue 5/31 */
#endif
#ifndef PRG32_COLOR_PURPLE
#define PRG32_COLOR_PURPLE 0x780F                       /* red 15/31, green 0/63, blue 15/31 */
#endif
#ifndef PRG32_COLOR_NAVY
#define PRG32_COLOR_NAVY 0x000F                         /* red 0/31, green 0/63, blue 15/31 */
#endif
#ifndef PRG32_COLOR_LIME
#define PRG32_COLOR_LIME 0x87E0                         /* red 16/31, green 63/63, blue 0/31 */
#endif
#ifndef PRG32_SCREEN_W
#define PRG32_SCREEN_W PRG32_GAME_W                     /* the game area is 320 pixels wide */
#endif
#ifndef PRG32_SCREEN_H
#define PRG32_SCREEN_H PRG32_GAME_H                     /* and 200 pixels high; (0, 0) is the top-left */
#endif

/* ==========================================================================
 * 2. KIT HELPER FUNCTIONS
 * Small functions the blocks need, written here so nothing is hidden.
 * Only the helpers this game uses are included. 'static' keeps a name
 * private to this file.
 * ========================================================================== */
/*
 * prg32_kit_format_number(out, value): write a whole number as decimal text.
 * A cartridge has no printf, so the digits are made by hand: value % 10 is the last
 * digit and value / 10 removes it. The digits come out last-first, so they are
 * collected in digits[] and then copied in reverse order.
 * '0' + d turns a digit 0..9 into its character code ('0' is 48 in ASCII).
 * Result: the number of characters written (the text ends with a 0 byte).
 *
 * prg32_kit_draw_number(x, y, value, fg, bg): format the number, then draw the text.
 */
static int prg32_kit_format_number(char *out, int value) {
    char digits[11];                                    /* room for the 10 digits of the largest int */
    /* the size without the sign; unsigned also works for -2147483648 */
    unsigned int magnitude = value < 0 ? 0u - (unsigned int)value : (unsigned int)value;
    int count = 0;                                      /* digits collected so far */
    int length = 0;                                     /* characters written to out */
    do {                                                /* do ... while runs at least once, so 0 prints as "0" */
        /* keep the last digit */
        digits[count++] = (char)('0' + magnitude % 10u);
        magnitude /= 10u;                               /* and remove it from the number */
    } while (magnitude != 0u && count < 10);            /* until no digits are left */
    if (value < 0) out[length++] = '-';                 /* a minus sign first */
    while (count > 0) out[length++] = digits[--count];  /* copy the digits, last one first */
    out[length] = '\0';                                 /* C text always ends with a 0 byte */
    return length;
}
static void prg32_kit_draw_number(int x, int y, int value, uint16_t fg, uint16_t bg) {
    char text[12];                                      /* sign + 10 digits + the final 0 byte */
    prg32_kit_format_number(text, value);               /* number -> text */
    prg32_gfx_text8(x, y, text, fg, bg);                /* text -> screen */
}

/* ==========================================================================
 * 4. GAME STATE
 * Variables declared outside any function keep their values from one frame
 * to the next. Every variable is a whole number (int); a list is an array.
 * ========================================================================== */
static int t = 0;                                       /* variable t, starts at 0 */

/* ==========================================================================
 * 5. LIFECYCLE FUNCTIONS
 * The firmware calls these three functions; their names must start with
 * the entry prefix 'audio_check'. 'void' means: no inputs, no result.
 * ========================================================================== */
/*
 * audio_check_init(): runs once when the cartridge starts (and again on restart).
 * First every variable and list gets its starting value, then the
 * 'when game starts' blocks run.
 */
void audio_check_init(void) {
    t = 0;                                              /* t starts again from 0 */
    /* Block "set t to 0": store 0 in the variable t. */
    t = 0;                                              /* C syntax: '=' stores the value on the right in the variable on the left */
    /* Block "set volume": master volume 160 (0 is silent, 255 is loudest). */
    prg32_audio_set_master_volume(160);
}

/*
 * audio_check_update(): runs once per frame, before drawing.
 * Game rules go here: read the buttons, move things, test collisions, keep score.
 */
void audio_check_update(void) {
    /* Block "if t == 0": the inner blocks run only when the condition is true (not 0). */
    if (t == 0) {                                       /* C syntax: if (condition) { ... }; any value except 0 counts as true */
        /* Block "play soundtrack Check": track 0 of the cartridge's audio block starts; voice N
         * plays instrument N. */
        prg32_audio_play_track(0);
    }                                                   /* end of if (t == 0) */
    /* Block "if t == 200": the inner blocks run only when the condition is true (not 0). */
    if (t == 200) {
        /* Block "play sound effect Drum": AudioStudio instrument 8 plays note 60 on voice 6 for 300
         * ms, then its envelope releases. */
        prg32_audio_note(6, 8, 60, 255, 300);
    }                                                   /* end of if (t == 200) */
    /* Block "if t == 230": the inner blocks run only when the condition is true (not 0). */
    if (t == 230) {
        /* Block "play sound effect Long": AudioStudio instrument 9 plays note 57 on voice 3 for
         * 5000 ms, then its envelope releases. */
        prg32_audio_note(3, 9, 57, 255, 5000);
    }                                                   /* end of if (t == 230) */
    /* Block "if t == 245": the inner blocks run only when the condition is true (not 0). */
    if (t == 245) {
        /* Block "stop all sounds": every voice goes silent at once. */
        prg32_audio_stop_all();
    }                                                   /* end of if (t == 245) */
    /* Block "change t by 1": add 1 to t. */
    t += 1;                                             /* C syntax: x += d is short for x = x + d */
    /* Block "if t == 330": the inner blocks run only when the condition is true (not 0). */
    if (t == 330) {
        /* Block "set t to 0": store 0 in the variable t. */
        t = 0;
    }                                                   /* end of if (t == 330) */
}

/*
 * audio_check_draw(): runs once per frame, after update.
 * Only painting goes here: the screen shows the state that update computed.
 */
void audio_check_draw(void) {
    /* Block "clear screen": paint the whole 320 x 200 game area black. */
    prg32_gfx_clear(PRG32_COLOR_BLACK);                 /* a firmware call: the PRG32 firmware does the drawing */
    /* Block "draw text": write "PRG32 AUDIO CHECK" with the 8x8 font at (8, 8), white on black. */
    /* text in quotes "..." is a C string: its characters followed by a 0 byte */
    prg32_gfx_text8(8, 8, "PRG32 AUDIO CHECK", PRG32_COLOR_WHITE, PRG32_COLOR_BLACK);
    /* Block "draw number": write the value of t in decimal digits at (8, 24), yellow on black. */
    /* kit helper: turns the number into text, then draws it */
    prg32_kit_draw_number(8, 24, t, PRG32_COLOR_YELLOW, PRG32_COLOR_BLACK);
}
